import java.util.List;
import java.util.Map;
import java.util.Set;

public class ClaimOffice {

    private static final int PROCESSING_FEE = 5;
    private static final double FIRST_INSURANCE_SURCHARGE_RATE = 0.10;

    /** The MHPCO price list: base premium in G per main item type. */
    private static final Map<String, Integer> MAIN_ITEM_BASE_PREMIUM_BY_TYPE = Map.of(
            "sword", 100,
            "amulet", 60,
            "staff", 80,
            "potion", 40);

    /**
     * Components are a family of small item types the MHPCO prices alike: every
     * component costs the same base premium, whatever its type.
     */
    private static final Set<String> COMPONENT_TYPES = Set.of("rune", "moonstone");

    private static final int COMPONENT_BASE_PREMIUM = 25;

    /**
     * Placeholder for types not yet in the price list. The specification treats an
     * unknown type as an error; until that behavior is implemented, unlisted types
     * fall back to the sword price rather than to an invented "unlisted item" price.
     */
    private static final int UNLISTED_TYPE_PLACEHOLDER_PREMIUM =
            MAIN_ITEM_BASE_PREMIUM_BY_TYPE.get("sword");

    private final Customer customer;

    public ClaimOffice(Customer customer) {
        this.customer = customer;
    }

    public int quote(List<Item> items) {
        double policyBasePremium = policyBasePremiumOf(items);
        double premiumBeforeFee = withPolicyWideModifiers(policyBasePremium);
        return roundInOfficeFavour(premiumBeforeFee + PROCESSING_FEE);
    }

    /** Sums the price-list base premium of every insured item. */
    private double policyBasePremiumOf(List<Item> items) {
        return items.stream().mapToDouble(ClaimOffice::basePremiumOf).sum();
    }

    private static double basePremiumOf(Item item) {
        if (isComponent(item)) {
            return COMPONENT_BASE_PREMIUM;
        }
        return MAIN_ITEM_BASE_PREMIUM_BY_TYPE.getOrDefault(
                item.type(), UNLISTED_TYPE_PLACEHOLDER_PREMIUM);
    }

    private static boolean isComponent(Item item) {
        return COMPONENT_TYPES.contains(item.type());
    }

    /** Modifiers that apply to the policy base premium as a whole. */
    private double withPolicyWideModifiers(double policyBasePremium) {
        return policyBasePremium
                + policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
    }

    /** A premium is rounded up: the MHPCO rounds in its own favour. */
    private static int roundInOfficeFavour(double premium) {
        return (int) Math.ceil(premium);
    }
}
